<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;
use App\Core\Csrf;
use App\Core\Database;
use App\Services\TestAutomaticJudgeService;
Auth::requireAdmin();
$pdo=Database::connection();
$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);
if($roundId<1){http_response_code(400);exit('Open a test round first.');}
TestAutomaticJudgeService::ensureSchema($pdo);
$roundStmt=$pdo->prepare('SELECT * FROM bdc_test_scoring_rounds WHERE id=:r');
$roundStmt->execute(['r'=>$roundId]);
$round=$roundStmt->fetch();
if(!$round){http_response_code(404);exit('Test round not found.');}
$mode=(string)($_POST['test_mode']??$_GET['test_mode']??$_SESSION['bdc_test_scoring_mode']??'automated');
if(!in_array($mode,['manual','automated'],true))$mode='automated';
$_SESSION['bdc_test_scoring_mode']=$mode;
$redirect=url('admin/scoring-tests/index.php?legacy=1&test_mode='.$mode.'&round_id='.$roundId);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid security token.');}
 $action=(string)($_POST['action']??'');
 try{
	  if($action==='regenerate_link'){
	   $judgeId=(int)($_POST['judge_id']??0);$token=TestAutomaticJudgeService::regenerate($pdo,$roundId,$judgeId);$_SESSION['bdc_test_auto_urls'][$roundId][$judgeId]=TestAutomaticJudgeService::publicUrl($token);
	  }elseif($action==='reopen_judge'){
	   $judgeId=(int)($_POST['judge_id']??0);TestAutomaticJudgeService::unlock($pdo,$roundId,$judgeId,(int)(Auth::user()['id']??0),trim((string)($_POST['reason']??'')));
  }elseif($action==='generate_and_submit_all'){
   TestAutomaticJudgeService::syncRound($pdo,$roundId);$pdo->beginTransaction();TestAutomaticJudgeService::generateAndSubmitAll($pdo,$roundId);$pdo->commit();
  }elseif($action==='generate_all_draft'){
   TestAutomaticJudgeService::syncRound($pdo,$roundId);$pdo->beginTransaction();TestAutomaticJudgeService::generateAllDraft($pdo,$roundId);$pdo->prepare("UPDATE bdc_test_scoring_rounds SET status='draft' WHERE id=:r")->execute(['r'=>$roundId]);$pdo->commit();
  }elseif($action==='delete_judge'){
   $judgeId=(int)($_POST['judge_id']??0);$pdo->beginTransaction();$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$roundId,'j'=>$judgeId]);$pdo->prepare('DELETE FROM bdc_test_scoring_judge_sessions WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$roundId,'j'=>$judgeId]);$pdo->prepare('DELETE FROM bdc_test_scoring_judges WHERE round_id=:r AND id=:j')->execute(['r'=>$roundId,'j'=>$judgeId]);$pdo->commit();unset($_SESSION['bdc_test_auto_urls'][$roundId][$judgeId]);
  }elseif($action==='delete_all_judges'){
   $pdo->beginTransaction();TestAutomaticJudgeService::clearJudgeSessions($pdo,$roundId);$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_judges WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->commit();unset($_SESSION['bdc_test_auto_urls'][$roundId]);
  }elseif($action==='delete_entry'){
   $entryId=(int)($_POST['entry_id']??0);$pdo->beginTransaction();$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND entry_id=:e')->execute(['r'=>$roundId,'e'=>$entryId]);$pdo->prepare('DELETE FROM bdc_test_scoring_results WHERE round_id=:r AND entry_id=:e')->execute(['r'=>$roundId,'e'=>$entryId]);$pdo->prepare('DELETE FROM bdc_test_scoring_entries WHERE round_id=:r AND id=:e')->execute(['r'=>$roundId,'e'=>$entryId]);$pdo->commit();
  }elseif($action==='delete_all_entries'){
   $pdo->beginTransaction();$pdo->prepare('DELETE FROM bdc_test_scoring_results WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_entries WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->commit();
  }elseif($action==='clear_round'){
   $pdo->beginTransaction();TestAutomaticJudgeService::clearJudgeSessions($pdo,$roundId);foreach(['bdc_test_scoring_results','bdc_test_scoring_marks','bdc_test_scoring_judges','bdc_test_scoring_entries'] as $table)$pdo->prepare("DELETE FROM {$table} WHERE round_id=:r")->execute(['r'=>$roundId]);$pdo->prepare("UPDATE bdc_test_scoring_rounds SET status='draft',generated_version=0,chief_judge_id=NULL WHERE id=:r")->execute(['r'=>$roundId]);$pdo->commit();unset($_SESSION['bdc_test_auto_urls'][$roundId]);
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['bdc_test_auto_error']=$e->getMessage();}
 header('Location: '.$redirect,true,303);exit;
}
$items=TestAutomaticJudgeService::syncRound($pdo,$roundId);
foreach($items as $item){$jid=(int)$item['id'];if(($item['plain_token']??'')!=='')$_SESSION['bdc_test_auto_urls'][$roundId][$jid]=TestAutomaticJudgeService::publicUrl((string)$item['plain_token']);}
$progress=TestAutomaticJudgeService::progress($pdo,$roundId);$urls=$_SESSION['bdc_test_auto_urls'][$roundId]??[];$error=(string)($_SESSION['bdc_test_auto_error']??'');unset($_SESSION['bdc_test_auto_error']);$csrf=Csrf::token();
$tieStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_test_scoring_results WHERE round_id=:r AND result_status='tie_pending'");
$tieStmt->execute(['r'=>$roundId]);
$hasCallbackTies=(int)$tieStmt->fetchColumn()>0;
$automaticScreen=url('admin/scoring-tests/automatic-screen.php');
?>
