   <input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="test_mode" value="automated"><input type="hidden" name="action" value="generate_and_submit_all">
   <button class="btn btn-success">Generate &amp; Submit All Judges</button>
