s_chief']?' <span class="badge text-bg-dark">Chief</span>':''?></td><td><?=e(ucfirst((string)$row['scoring_scope']))?></td><td><?php $badge=$status==='submitted'?'success':($status==='scoring'?'primary':'secondary');?><span class="badge text-bg-<?=$badge?>"><?=e(ucwords(str_replace('_',' ',$status)))?></span></td><td><div class="progress" style="height:8px"><div class="progress-bar" style="width:<?=(int)$row['percent']?>%"></div></div><div class="small mt-1"><?=(int)$row['done']?> / <?=(int)$row['total']?> scored · <?=(int)$row['percent']?>%</div></td><td><?php if($judgeUrl!==''):?><div class="input-group input-group-sm" style="min-width:320px"><input class="form-control" readonly value="<?=e($judgeUrl)?>"><button type="button" class="btn btn-outline-primary" onclick="navigator.clipboard.writeText(this.previousElementSibling.value)">Copy</button><a class="btn btn-outline-dark" target="_blank" href="<?=e($judgeUrl)?>">Open</a></div><?php else:?><span class="text-muted small">Existing token hidden. Regenerate to reveal a new URL.</span><?php endif;?></td><td><div class="d-flex gap-1 flex-wrap"><form method="post" action="<?=e(url('admin/scoring-tests/automatic-inline.php'))?>"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="test_mode" value="automated"><input type="hidden" name="judge_id" value="<?=$jid?>"><input type="hidden" name="action" value="regenerate_link"><button class="btn btn-sm btn-outline-primary">Regenerate</button></form><form method="post" action="<?=e(url('admin/scoring-tests/automatic-inline.php'))?>" onsubmit="return confirm('Delete this judge and their test marks?')"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="test_mode" value="automated"><input type="hidden" name="judge_id" value="<?=$jid?>"><input type="hidden" name="action" value="delete_judge"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><div class="small text-muted mt-3">Submitted judges are locked on their judge URL. The shared BDC calculation engine remains unchanged.</div><?php endif;?></div></div>
