<script>(function(){const rid=<?=$roundId?>,dataUrl=<?=json_encode(url('admin/scoring-tests/automatic-live-data.php?round_id='.$roundId),JSON_UNESCAPED_SLASHES)?>;let data=null,original=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function rows(){let a=[...data.entries],mode=document.getElementById('testMatrixSort').value;if(mode==='score_asc')a.sort((x,y)=>(x.score??99999)-(y.score??99999));else if(mode==='bib')a.sort((x,y)=>(x.bib_number??x.pair_number)-(y.bib_number??y.pair_number));else if(mode==='name')a.sort((x,y)=>String(x.display_name??x.leader_name).localeCompare(String(y.display_name??y.leader_name)));else if(mode==='original')a=original.map(id=>a.find(x=>(x.id??x.pair_id)===id)).filter(Boolean);else if(data.round_type!=='final')a.sort((x,y)=>(y.score??0)-(x.score??0));return a}function paint(){document.getElementById('testMatrixHead').innerHTML='<tr><th>Provisional</th><th>Competitor / Couple</th>'+data.judge_columns.map(j=>'<th>J'+j.judge_order+'<br><small>'+esc(j.judge_name)+'</small></th>').join('')+(data.round_type==='final'?'':'<th>Score</th>')+'</tr>';document.getElementById('testMatrixBody').innerHTML=rows().map((x,i)=>'<tr><td>'+(data.round_type==='final'?'—':i+1)+'</td><td>'+(data.round_type==='final'?'Couple '+x.pair_number+'<br>'+esc(x.leader_name)+' &amp; '+esc(x.follower_name):'#'+x.bib_number+' '+esc(x.display_name)+'<br><small>'+esc(x.dance_role)+'</small>')+'</td>'+data.judge_columns.map(j=>'<td>'+esc(x.marks[j.id]??'—')+'</td>').join('')+(data.round_type==='final'?'':'<td><strong>'+Number(x.score).toFixed(1)+'</strong></td>')+'</tr>').join('')}async function tick(){try{const r=await fetch(dataUrl+'&_='+Date.now(),{cache:'no-store'}),j=await r.json();if(j.ok){if(!data)original=j.entries.map(x=>x.id??x.pair_id);data=j;paint()}}catch(e){}}document.getElementById('testMatrixSort').onchange=()=>data&&paint();tick();setInterval(tick,1000)})();</script>
<script>(function(){const card=document.getElementById('testCompetitorMatrix'),sourceBody=document.getElementById('testMatrixBody'),sourceHead=document.getElementById('testMatrixHead'),sourceWrap=sourceBody.closest('.table-responsive');if(!card||!sourceBody||!sourceHead||!sourceWrap)return;const style=document.createElement('style');style.textContent='.test-split-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:12px}.test-role-pane{min-width:0;border:1px solid #ced4da;border-radius:8px;overflow:hidden;background:#fff}.test-role-title{padding:9px 12px;font-weight:800}.test-role-scroll{overflow-x:auto;overflow-y:auto;max-height:70vh;scrollbar-gutter:stable}.test-role-scroll table{width:max-content;min-width:100%;margin:0}.test-role-scroll th,.test-role-scroll td{min-width:58px;white-space:nowrap}.test-role-scroll th:first-child,.test-role-scroll td:first-child{position:sticky;left:0;z-index:3;background:#fff;min-width:72px}.test-role-scroll th:nth-child(2),.test-role-scroll td:nth-child(2){position:sticky;left:72px;z-index:3;background:#fff;min-width:190px;white-space:normal}.test-role-scroll thead th{position:sticky;top:0;z-index:4;background:#f8f9fa}.test-role-scroll thead th:first-child,.test-role-scroll thead th:nth-child(2){z-index:6;background:#f8f9fa}@media(max-width:1100px){.test-split-grid{grid-template-columns:1fr}}';document.head.appendChild(style);const host=document.createElement('div');host.className='test-split-grid';host.innerHTML='<section class="test-role-pane"><div class="test-role-title bg-primary-subtle">LEADERS</div><div class="test-role-scroll"><table class="table table-bordered table-sm"><thead data-role-head="leader"></thead><tbody data-role-body="leader"></tbody></table></div></section><section class="test-role-pane"><div class="test-role-title bg-danger-subtle">FOLLOWERS</div><div class="test-role-scroll"><table class="table table-bordered table-sm"><thead data-role-head="follower"></thead><tbody data-role-body="follower"></tbody></table></div></section>';sourceWrap.after(host);sourceWrap.style.display='none';function render(){const rows=[...sourceBody.querySelectorAll('tr')];const roleRows=rows.filter(row=>/^(leader|follower)$/.test(row.querySelector('td:nth-child(2) small')?.textContent.trim().toLowerCase()||''));if(!roleRows.length){sourceWrap.style.display='block';host.style.display='none';return}sourceWrap.style.display='none';host.style.display='grid';['leader','follower'].forEach(role=>{host.querySelector('[data-role-head="'+role+'"]').innerHTML=sourceHead.innerHTML;const target=host.querySelector('[data-role-body="'+role+'"]');target.innerHTML='';roleRows.filter(row=>(row.querySelector('td:nth-child(2) small')?.textContent.trim().toLowerCase()||'')===role).forEach((row,index)=>{const clone=row.cloneNode(true),rank=clone.querySelector('td:first-child');if(rank)rank.textContent=String(index+1);target.appendChild(clone)})})}new MutationObserver(render).observe(sourceBody,{childList:true});render()})();</script>
<script>(function(){const workflowEndpoint=window.location.href,screenBase=<?=json_encode($automaticScreen,JSON_UNESCAPED_SLASHES)?>,status=document.getElementById('automaticWorkflowStatus');document.querySelectorAll('[data-auto-workflow-form]').forEach(form=>form.addEventListener('submit',async event=>{if(event.defaultPrevented)return;event.preventDefault();const button=form.querySelector('button');button.disabled=true;status.className='small text-muted mt-3';status.textContent='Processing Test round…';try{const response=await fetch(workflowEndpoint,{method:'POST',body:new FormData(form),credentials:'same-origin',cache:'no-store'});const html=await response.text();if(!response.ok)throw new Error('Request failed with HTTP '+response.status);const doc=new DOMParser().parseFromString(html,'text/html');const error=doc.querySelector('.alert-danger');if(error)throw new Error(error.textContent.trim());const nextRound=Number(doc.querySelector('input[name="round_id"]')?.value||<?=$roundId?>);window.top.location.href=screenBase+'?round_id='+nextRound}catch(error){button.disabled=false;status.className='small text-danger mt-3';status.textContent=String(error.message||error)}}))})();</script>
<script>window.decorateTestJudgePanel=function(){document.querySelectorAll('#automaticJudgeLivePanel tbody tr').forEach(row=>{const input=row.querySelector('input.form-control'),actions=row.querySelector('td:last-child .d-flex');if(!input||!actions||actions.dataset.enhanced)return;actions.dataset.enhanced='1';const url=input.value,name=row.querySelector('td strong')?.textContent.trim()||'Judge',eventName=<?=json_encode((string)($round['event_name']??'BDC Competition'))?>,division=<?=json_encode(ucwords(str_replace('_',' ',(string)$round['division'])))?>,roundType=<?=json_encode(ucfirst((string)$round['round_type']))?>,message='Hi '+name+',\n\nHere is your secure BDC judging link for '+eventName+' — '+division+' — '+roundType+'.\n\n'+url+'\n\nPlease review the judging criteria, complete your scoring independently, and press Submit & Lock when finished. Keep this secure link confidential.';actions.insertAdjacentHTML('afterbegin','<a class="btn btn-sm btn-outline-success" target="_blank" rel="noopener" href="https://wa.me/?text='+encodeURIComponent(message)+'">WhatsApp</a><a class="btn btn-sm btn-outline-primary" href="mailto:?subject='+encodeURIComponent('IMPORTANT — BDC Judge Scoring Link — '+eventName)+'&body='+encodeURIComponent('IMPORTANT: Secure judging access\n\n'+message)+'">Email Important</a>');if(row.querySelector('.badge.text-bg-success')){const judgeId=actions.querySelector('input[name="judge_id"]')?.value;if(judgeId)actions.insertAdjacentHTML('beforeend','<form method="post" action="<?=e(url('admin/scoring-tests/automatic-inline.php'))?>" onsubmit="const reason=prompt(\'Reason for reopening this judge?\');if(!reason)return false;this.reason.value=reason;return confirm(\'Reopen scoring and retain all existing marks?\')"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="test_mode" value="automated"><input type="hidden" name="judge_id" value="'+judgeId+'"><input type="hidden" name="action" value="reopen_judge"><input type="hidden" name="reason"><button class="btn btn-sm btn-outline-warning">Reopen Scoring</button></form>')}})};window.decorateTestJudgePanel();</script>
<script>(function(){const endpoint=<?=json_encode(url('admin/scoring-tests/automatic-inline.php?round_id='.$roundId.'&test_mode=automated'),JSON_UNESCAPED_SLASHES)?>;setTimeout(function refresh(){fetch(endpoint,{headers:{'X-Requested-With':'XMLHttpRequest'},cache:'no-store'}).then(r=>r.text()).then(html=>{const current=document.getElementById('automaticJudgeLivePanel');if(!current)return;const box=document.createElement('div');box.innerHTML=html;const fresh=box.querySelector('#automaticJudgeLivePanel');if(fresh){current.replaceWith(fresh);window.decorateTestJudgePanel?.()}}).catch(()=>{});setTimeout(refresh,1000);},1000);})();</script>
